DO $fix$ DECLARE cid uuid := '35512cdd-3b6c-4039-b98d-cbd3ff8a6810'; props jsonb; BEGIN SELECT jsonb_agg(CASE WHEN p LIKE 'Penilaian: station prosedural%' THEN 'Penilaian: oral board 600 detik; peserta menjelaskan pemeriksaan dan teknik DUS menggunakan laporan teks. Demonstrasi alat opsional bila tersedia.' WHEN p LIKE 'Stoking kompresi kelas%' THEN 'Contoh stoking bawah lutut tekanan 20–30 dan 30–40 mmHg; kelas mengikuti standar produsen.' ELSE p END ORDER BY n) INTO props FROM public.case_answer_keys a CROSS JOIN LATERAL jsonb_array_elements_text(a.checklist_rubric->'properties') WITH ORDINALITY e(p,n) WHERE a.case_id=cid; UPDATE public.case_answer_keys SET checklist_rubric=jsonb_set(checklist_rubric,'{properties}',props) WHERE case_id=cid; UPDATE public.clinical_cases SET properties=ARRAY(SELECT jsonb_array_elements_text(props)) WHERE id=cid; END $fix$;